        k = s
        while k > 0:
            nr, nc = r+dy*k, c+dx*k
            if nr >= 0 and nc >= 0 and free(bc,bd,nr,nc,s): break
            k -= 1
        nr, nc = r+dy*k, c+dx*k
        cost = 1; nt = tile
