    if a == 'PLUS': return ((r,c,2,bc,bd,tile) if s == 4 else st), 5, False
    if a == 'COL':
        return (r,c,s, bc and not gap(r,c,s,CBOX) <= T, bd and not gap(r,c,s,DBOX) <= T, tile), 4, False
    return (((18,34) if s == 2 else (17,33)) + (s,bc,bd,tile)), 4, False
s0 = (29,17,4,True,True,True)
